                module Wireframe
                module DrawScannerMarkerSegment
; -----------------------------------------
; вывод отрезка маркера сканера с изменяемыми командами шага
; исходный диапазон #B440..#B4B0
; In:
;   HL, два однобайтовых кода шага координат B/C
;   DE, E содержит ненулевую длину
;   BC, начальные координаты
; Out:
;   HL, DE, BC, исходные значения
; Corrupt:
;   AF
; Note:
; два байта HL записываются в ScannerRaster.StepOpcodes и следующий байт, это команды шага B/C
; Вызывающий код подставляет INC/DEC B/C и NOP, после каждого шага рисуется пиксель.
; ObjectEffects.Current хранит указатель текущих расширенных метаданных, далее лежит рабочая область записей объектов.
; -----------------------------------------
                ; проверка исходного начала фрагмента
                ASSERT $ == #B440
                ; сохранение координат и установка двух команд шага
Entry:          PUSH BC
                PUSH DE
                PUSH HL
                LD (ScannerRaster.StepOpcodes), HL
                ; самомодифицируемый шаг координат перед очередным пикселем
StepOpcodes     EQU $                                                           ; два кода INC/DEC B/C либо NOP, шаг отрезка маркера
DrawPixel:      NOP
                NOP
                CALL Game.Motion.XorFarObjectPixel.Entry
                DEC E
                JR NZ, DrawPixel                                                ; переход, если ещё не выведены все пиксели отрезка

                POP HL
                POP DE
                POP BC
                RET

                ; данные указателя и рабочей области расширенных метаданных объектов
EffectData      FObjectEffects {                                                ; явные исходные значения полей
                    Game.Wireframe.DrawScannerMarkerSegment.EffectData.Scratch, ; FObjectEffects.Current, указатель текущей FEffectRecord10
                    #00,                                                        ; FObjectEffects.Phase, фаза 1..3 в младших двух битах
                    #00,                                                        ; FObjectEffects.Remaining, счётчик оставшихся слотов, 8..1
                    #00                                                         ; FObjectEffects.Flags, общие признаки взаимодействия
                }
.Records        FEffectRecord10 {                                               ; запись 0, FEffectRecord10
                    #00,                                                        ; FEffectRecord10.TypeFlags, +00, тип и признаки, младшие два бита группа, #A0..#A7 фаза кругового эффекта
                    #00,                                                        ; FEffectRecord10.FirstFlags, +01, признаки первой экранной точки, #FF означает отсутствие проекции
                    #00,                                                        ; FEffectRecord10.FirstX, +02, модуль горизонтальной координаты первой точки
                    #00,                                                        ; FEffectRecord10.FirstY, +03, модуль вертикальной координаты первой точки
                    #00,                                                        ; FEffectRecord10.SecondFlags, +04, признаки второй экранной точки, #FF означает отсутствие проекции
                    #00,                                                        ; FEffectRecord10.SecondX, +05, модуль горизонтальной координаты второй точки
                    #00,                                                        ; FEffectRecord10.SecondY, +06, модуль вертикальной координаты второй точки
                    #00,                                                        ; FEffectRecord10.Timer, +07, обратный отсчёт взаимодействия, начальное значение #18
                    #00,                                                        ; FEffectRecord10.Links, +08, младшая тетрада текущая ссылка, старшая тетрада предыдущая ссылка
                    #00                                                         ; FEffectRecord10.Fallback, +09, резервная ссылка в младшей тетраде, бит 7 запрещает резерв станции
                }

